export async function loader() {
  try {
    const seoRes = await axios.get(`${BASE_URL}${seoBySlugAPI}become-host`).catch(() => null);
    return {
      seoData: seoRes?.data?.data || null,
    };
  } catch (error) {
    return { seoData: null };
  }
}

export function meta({ data, params }) {
  const lang = params.lang || "en";
  const canonicalBase = (import.meta.env.VITE_CANONICAL_URL || "https://flexsirent.com").replace(/\/+$/, "");
  const url = `${canonicalBase}/${lang}/become-a-host`;
  const seo = data?.seoData;
  const title = seo?.meta_title || "Become a Host | Flexsirent";
  const description = seo?.meta_description || "List your property, room, or apartment on Flexsirent. Reach verified mid-term renters and secure bookings.";

  return [
    { title },
    { name: "description", content: description },
    { property: "og:title", content: title },
    { property: "og:description", content: description },
    { property: "og:url", content: url },
    { tagName: "link", rel: "canonical", href: url }
  ];
}

